     1	/**
     2	 * Membership rows. Every read is filtered by `orgId`; removal is a soft delete.
     3	 *
     4	 * Must call (do not reimplement): archivePatch, shouldFilterArchived
     5	 */
     6	import { and, count, desc, eq, isNull, like, or } from "drizzle-orm";
     7	import { newId } from "@/lib/id";
     8	import { archivePatch, shouldFilterArchived } from "@/lib/soft-delete";
     9	import { getDb, members, users } from "@/server/db";
    10	import { toIsoTimestamp } from "@/types/common";
    11	import { orgPredicate } from "./base-repository";
    12	import { compact, keysetPredicate, probeLimit, toPage } from "./_paging";
    13	import { toMember, toUser } from "./_mappers";
    14	import type { ListMembersInput } from "@/schemas/member";
    15	import type { IsoTimestamp, MemberId, OrgId, Page, UserId } from "@/types/common";
    16	import type { Member, MemberWithUser, Role } from "@/types/member";
    17	
    18	/**
    19	 * A removed member is archived, never deleted, and no read ever surfaces one:
    20	 * the scope is fixed here rather than threaded through every call site.
    21	 */
    22	const LIVE_MEMBERS: { readonly includeArchived?: boolean } = {};
    23	
    24	function liveMemberPredicate() {
    25	  return shouldFilterArchived(LIVE_MEMBERS) ? isNull(members.archivedAt) : undefined;
    26	}
    27	
    28	/**
    29	 * The (org, user) lookup behind every actor resolution. The pair is unique,
    30	 * so the row itself says whether the membership is usable: callers read
    31	 * `status`, and an ended membership keeps its `archivedAt` for the audit log.
    32	 */
    33	export async function findMember(
    34	  orgId: OrgId,
    35	  userId: UserId,
    36	): Promise<Member | null> {
    37	  const row = getDb()
    38	    .select()
    39	    .from(members)
    40	    .where(and(orgPredicate(members.orgId, orgId), eq(members.userId, userId)))
    41	    .get();
    42	  return row ? toMember(row) : null;
    43	}
    44	
    45	export async function findMemberById(
    46	  orgId: OrgId,
    47	  memberId: MemberId,
    48	): Promise<Member | null> {
    49	  const row = getDb()
    50	    .select()
    51	    .from(members)
    52	    .where(and(orgPredicate(members.orgId, orgId), eq(members.id, memberId)))
    53	    .get();
    54	  return row ? toMember(row) : null;
    55	}
    56	
    57	/** Cursor-paged member list joined with the user record the UI renders. */
    58	export async function listMembers(
    59	  input: ListMembersInput,
    60	): Promise<Page<MemberWithUser>> {
    61	  const db = getDb();
    62	  const sort = { sortColumn: members.createdAt, idColumn: members.id };
    63	
    64	  const filters = compact(
    65	    orgPredicate(members.orgId, input.orgId),
    66	    liveMemberPredicate(),
    67	    input.role === undefined ? undefined : eq(members.role, input.role),
    68	    input.status === undefined ? undefined : eq(members.status, input.status),
    69	    input.query === undefined
    70	      ? undefined
    71	      : or(
    72	          like(users.name, `%${input.query}%`),
    73	          like(users.email, `%${input.query}%`),
    74	        ),
    75	  );
    76	
    77	  const total = db
    78	    .select({ value: count() })
    79	    .from(members)
    80	    .innerJoin(users, eq(users.id, members.userId))
    81	    .where(and(...filters))
    82	    .get();
    83	
    84	  const rows = db
    85	    .select({ member: members, user: users })
    86	    .from(members)
    87	    .innerJoin(users, eq(users.id, members.userId))
    88	    .where(and(...filters, ...compact(keysetPredicate(sort, input.cursor))))
    89	    .orderBy(desc(members.createdAt), desc(members.id))
    90	    .limit(probeLimit(input.limit))
    91	    .all();
    92	
    93	  return toPage(
    94	    rows,
    95	    input.limit,
    96	    total?.value ?? 0,
    97	    (row) => ({ ...toMember(row.member), user: toUser(row.user) }),
    98	    (row) => ({ id: row.member.id, sortValue: row.member.createdAt }),
    99	  );
   100	}
   101	
   102	/** The seat count every plan check compares against. */
   103	export async function countActiveMembers(orgId: OrgId): Promise<number> {
   104	  const row = getDb()
   105	    .select({ value: count() })
   106	    .from(members)
   107	    .where(
   108	      and(
   109	        orgPredicate(members.orgId, orgId),
   110	        eq(members.status, "active"),
   111	        liveMemberPredicate(),
   112	      ),
   113	    )
   114	    .get();
   115	  return row?.value ?? 0;
   116	}
   117	
   118	export async function insertMember(
