    18	/**
    19	 * A removed member is archived, never deleted, and no read ever surfaces one:
    20	 * the scope is fixed here rather than threaded through every call site.
    21	 */
    22	const LIVE_MEMBERS: { readonly includeArchived?: boolean } = {};
    23	
    24	function liveMemberPredicate() {
    25	  return shouldFilterArchived(LIVE_MEMBERS) ? isNull(members.archivedAt) : undefined;
    26	}
    27	
    28	/**
    29	 * The (org, user) lookup behind every actor resolution. The pair is unique,
    30	 * so the row itself says whether the membership is usable: callers read
    31	 * `status`, and an ended membership keeps its `archivedAt` for the audit log.
    32	 */
    33	export async function findMember(
    34	  orgId: OrgId,
    35	  userId: UserId,
    36	): Promise<Member | null> {
    37	  const row = getDb()
    38	    .select()
    39	    .from(members)
    40	    .where(and(orgPredicate(members.orgId, orgId), eq(members.userId, userId)))
    41	    .get();
    42	  return row ? toMember(row) : null;
    43	}
