    16	/** How long a freshly issued session cookie stays valid. */
    17	const SESSION_TTL_DAYS = 30;
    18	const MS_PER_DAY = 24 * 60 * 60 * 1000;
    19	
    20	/** Length in bytes of the raw session token handed to the browser. */
    21	const TOKEN_BYTES = 32;
    22	
    23	/**
    24	 * Mints a session. Only the hash reaches the database, so a dump of the
    25	 * `sessions` table cannot be replayed as a login.
    26	 */
    27	export async function createSessionToken(
    28	  userId: UserId,
    29	): Promise<{ token: string; expiresAt: IsoTimestamp }> {
    30	  const token = randomToken(TOKEN_BYTES);
    31	  const expiresAt = toIsoTimestamp(
    32	    new Date(Date.now() + SESSION_TTL_DAYS * MS_PER_DAY),
    33	  );
    34	
    35	  await sessionRepo.createSession(userId, hashToken(token), expiresAt);
    36	
    37	  return { token, expiresAt };
    38	}
    39	
    40	export async function resolveSession(
    41	  token: string,
    42	): Promise<SessionPrincipal | null> {
    43	  return sessionRepo.findSessionByTokenHash(hashToken(token));
    44	}
    45	
    46	/**
    47	 * The bridge between "who is logged in" and "what may they do here": given a
    48	 * principal and the org slug in the URL, produce the `Actor` every service
    49	 * method takes, or `null` when the user is not a member of that org.
    50	 *
    51	 * The `assertOrgScope` call at the end looks redundant — the actor was just
    52	 * built from that org — but it is the invariant this whole layer exists to
    53	 * uphold, and it catches a mis-wired membership lookup immediately.
    54	 */
    55	export async function resolveActorForOrg(
    56	  principal: SessionPrincipal,
    57	  orgSlug: string,
    58	): Promise<Actor | null> {
    59	  const org = await orgRepo.findOrgBySlug(orgSlug);
    60	  if (!org) return null;
    61	
    62	  const member = await memberRepo.findMember(org.id, principal.userId);
    63	  if (!member || member.status !== "active") return null;
    64	
    65	  const actor: Actor = {
    66	    userId: principal.userId,
    67	    orgId: org.id,
    68	    role: member.role,
    69	  };
    70	
    71	  assertOrgScope(actor, org.id);
    72	
    73	  await memberRepo.touchLastSeen(
    74	    org.id,
    75	    principal.userId,
    76	    toIsoTimestamp(new Date()),
    77	  );
    78	
    79	  return actor;
    80	}
    81	
    82	/**
    83	 * Switches the org a session defaults to. Membership is re-checked here so a
    84	 * removed member cannot pin their cookie to an org they left.
    85	 *
    86	 * `SessionPrincipal` carries no session id, so the write to `sessions.
    87	 * active_org_id` (`sessionRepository.setActiveOrg`) happens in the Server
    88	 * Action, which still holds the cookie. This method owns the authorization
    89	 * half of the switch.
    90	 */
    91	export async function switchActiveOrg(
    92	  principal: SessionPrincipal,
    93	  input: SwitchOrgInput,
    94	): Promise<void> {
    95	  const member = await memberRepo.findMember(input.orgId, principal.userId);
    96	  if (!member || member.status !== "active") {
    97	    throw new Error("You are not a member of that organization");
    98	  }
    99	
   100	  const orgs = await orgRepo.listOrgsForUser(principal.userId);
   101	  const target = orgs.find((org) => org.id === input.orgId);
   102	  if (!target) throw new Error("You are not a member of that organization");
   103	
   104	  assertOrgScope(
   105	    { userId: principal.userId, orgId: input.orgId, role: member.role },
   106	    target.id,
   107	  );
   108	}
   109	
   110	/**
   111	 * Logs a session out. The row is removed by expiring it: `SessionPrincipal`
   112	 * exposes no session id, so the sweep is what actually clears the row, and the
   113	 * cookie is dropped by the caller either way.
   114	 */
   115	export async function destroySession(token: string): Promise<void> {
   116	  const principal = await resolveSession(token);
   117	  if (!principal) return;
   118	
   119	  await sessionRepo.purgeExpiredSessions(toIsoTimestamp(new Date()));
   120	}
