     1	"use server";
     2	
     3	/**
     4	 * Accepts an invitation token and creates the membership.
     5	 *
     6	 * Owner D. Runs for a signed-in user who is *not yet* a member of the target
     7	 * org, so there is no `Actor` to resolve and the action cannot use
     8	 * `withAction()`. The seat quota is re-checked at acceptance time because the
     9	 * organization may have filled up since the invitation was sent.
    10	 *
    11	 * Must call (do not reimplement): acceptInvitationTokenSchema, getPlanLimits
    12	 */
    13	
    14	import { PlanLimitError, UnauthorizedActionError } from "@/actions/_lib/action-errors";
    15	import { getPlanLimits } from "@/config/plan-limits";
    16	import { toActionResult } from "@/lib/errors";
    17	import { getSessionPrincipal } from "@/lib/session";
    18	import { acceptInvitationTokenSchema } from "@/schemas/invitation";
    19	import { acceptInvitation } from "@/server/services/invitation-service";
    20	import { resolveActor } from "@/server/services/member-service";
    21	import { getOrganizationSummary } from "@/server/services/organization-service";
    22	import type { ActionResult } from "@/types/api";
    23	import type { Member } from "@/types/member";
    24	
    25	export async function acceptInvitationAction(raw: unknown): Promise<ActionResult<Member>> {
    26	  const parsed = acceptInvitationTokenSchema.safeParse(raw);
    27	  if (!parsed.success) {
    28	    return toActionResult(parsed.error);
    29	  }
    30	
    31	  try {
    32	    const principal = await getSessionPrincipal();
    33	    if (principal === null) {
    34	      throw new UnauthorizedActionError("Sign in before accepting an invitation.");
    35	    }
    36	
    37	    const member = await acceptInvitation(principal.userId, parsed.data);
    38	    await assertSeatAvailable(member);
    39	
    40	    return { ok: true, data: member, submittedAt: new Date().toISOString() };
    41	  } catch (error) {
    42	    return toActionResult(error);
    43	  }
    44	}
    45	
    46	/**
    47	 * Confirms the newly created membership still fits the plan. Reading usage
    48	 * requires an actor inside the org, which only exists once the membership row
    49	 * has been written — hence the check runs after `acceptInvitation`.
    50	 */
    51	async function assertSeatAvailable(member: Member): Promise<void> {
    52	  const actor = await resolveActor(member.userId, member.orgId);
    53	  if (actor === null) {
    54	    throw new UnauthorizedActionError("That invitation is no longer valid.");
    55	  }
    56	
    57	  const summary = await getOrganizationSummary(actor, member.orgId);
    58	  const limits = getPlanLimits(summary.organization.plan);
    59	  if (summary.usage.seatsUsed > limits.seats) {
    60	    throw new PlanLimitError("seats", limits.seats, summary.usage.seatsUsed);
    61	  }
    62	}
----- remove-member
     1	"use server";
     2	
     3	/**
     4	 * Removes a member (soft delete) and frees the seat.
     5	 *
     6	 * Owner D. The membership row is archived rather than deleted so that issues
     7	 * and comments authored by the person keep resolving their author.
     8	 *
     9	 * Must call (do not reimplement): removeMemberSchema, can, getActor,
    10	 * toActionResult
    11	 */
    12	
    13	import { ForbiddenActionError } from "@/actions/_lib/action-errors";
    14	import { withAction } from "@/actions/_lib/with-action";
    15	import { CACHE_PROFILES, orgTag, revalidateTagged } from "@/lib/cache";
    16	import { can } from "@/lib/permissions";
    17	import { removeMemberSchema, type RemoveMemberInput } from "@/schemas/member";
    18	import { removeMember } from "@/server/services/member-service";
    19	import type { ActionResult } from "@/types/api";
    20	import type { Member } from "@/types/member";
    21	
    22	const run = withAction<typeof removeMemberSchema, Member>(
    23	  removeMemberSchema,
    24	  async (raw, actor) => {
    25	    const input = raw as RemoveMemberInput;
    26	
    27	    const allowed = can(actor, "member:remove", {
    28	      kind: "member",
    29	      orgId: input.orgId,
    30	      memberId: input.memberId,
    31	      targetUserId: actor.userId,
    32	      targetRole: actor.role,
    33	    });
    34	    if (!allowed) {
    35	      throw new ForbiddenActionError("member:remove");
    36	    }
    37	
    38	    const member = await removeMember(actor, input);
    39	    revalidateTagged([orgTag(input.orgId)], CACHE_PROFILES.minutes);
    40	    return member;
    41	  },
    42	  { revalidate: ["members"], cacheProfile: "minutes" },
    43	);
    44	
    45	export async function removeMemberAction(raw: unknown): Promise<ActionResult<Member>> {
    46	  return run(raw);
    47	}
----- update-member-role
     1	"use server";
     2	
     3	/**
     4	 * Changes a member's role, keeping at least one owner.
     5	 *
     6	 * Owner D. Two guards that are easy to get wrong: nobody may grant a role above
     7	 * their own (`hasRoleAtLeast`), and the last owner may not be demoted —
     8	 * `MemberService.assertLastOwnerRetained` owns that second rule because it
     9	 * needs to count owners.
    10	 *
    11	 * Must call (do not reimplement): updateMemberRoleSchema, can, hasRoleAtLeast,
    12	 * getActor, toActionResult
    13	 */
    14	
    15	import { ForbiddenActionError } from "@/actions/_lib/action-errors";
    16	import { withAction } from "@/actions/_lib/with-action";
    17	import { CACHE_PROFILES, orgTag, revalidateTagged } from "@/lib/cache";
    18	import { can } from "@/lib/permissions";
    19	import {
    20	  updateMemberRoleSchema,
    21	  type UpdateMemberRoleInput,
    22	} from "@/schemas/member";
    23	import {
    24	  assertLastOwnerRetained,
    25	  updateMemberRole,
    26	} from "@/server/services/member-service";
    27	import type { ActionResult } from "@/types/api";
    28	import { hasRoleAtLeast, type Member } from "@/types/member";
    29	
    30	const run = withAction<typeof updateMemberRoleSchema, Member>(
    31	  updateMemberRoleSchema,
    32	  async (raw, actor) => {
    33	    const input = raw as UpdateMemberRoleInput;
    34	
    35	    const allowed = can(actor, "member:update_role", {
    36	      kind: "member",
    37	      orgId: input.orgId,
    38	      memberId: input.memberId,
    39	      targetUserId: actor.userId,
    40	      targetRole: input.role,
    41	    });
    42	    if (!allowed) {
    43	      throw new ForbiddenActionError("member:update_role");
    44	    }
    45	
    46	    // Privilege escalation guard: an admin cannot mint an owner.
    47	    if (!hasRoleAtLeast(actor.role, input.role)) {
    48	      throw new ForbiddenActionError("member:update_role");
    49	    }
    50	
    51	    await assertLastOwnerRetained(input.orgId, input.memberId, input.role);
    52	
    53	    const member = await updateMemberRole(actor, input);
    54	    revalidateTagged([orgTag(input.orgId)], CACHE_PROFILES.minutes);
    55	    return member;
    56	  },
    57	  { revalidate: ["members"], cacheProfile: "minutes" },
    58	);
    59	
    60	export async function updateMemberRoleAction(raw: unknown): Promise<ActionResult<Member>> {
    61	  return run(raw);
    62	}

