     1	/**
     2	 * Seat quota and invite rate limiting.
     3	 *
     4	 * Owner C implements `@/server/services/invitation-service`.
     5	 */
     6	import { afterAll, afterEach, beforeAll, describe, expect, it, vi } from "vitest";
     7	
     8	vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
     9	vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);
    10	vi.mock("@/lib/rate-limit", async () => (await import("../server/_support/doubles/misc")).rateLimitModule);
    11	
    12	import { subscribe } from "@/lib/event-bus";
    13	import { hashToken } from "@/lib/hash";
    14	import { PermissionDeniedError } from "@/lib/permissions";
    15	import * as invitationRepo from "@/server/repositories/invitation-repository";
    16	import * as memberRepo from "@/server/repositories/member-repository";
    17	import * as userRepo from "@/server/repositories/user-repository";
    18	import * as invitationService from "@/server/services/invitation-service";
    19	import { rateLimitState } from "../server/_support/doubles/misc";
    20	import { createTenant, useTemporaryDatabase } from "../server/_support/fixtures";
    21	import type { Unsubscribe } from "@/types/event";
    22	
    23	let cleanup: () => void;
    24	
    25	beforeAll(async () => {
    26	  cleanup = await useTemporaryDatabase();
    27	});
    28	
    29	afterAll(() => {
    30	  cleanup();
    31	});
    32	
    33	afterEach(() => {
    34	  rateLimitState.allowed = true;
    35	  rateLimitState.remaining = 100;
    36	});
    37	
    38	describe("services/invitation-service", () => {
    39	  // can(actor, "member:invite", …) — a member cannot invite, an admin can.
    40	  it("refuses an invite from an actor without member:invite", async () => {
    41	    const tenant = await createTenant("invite-forbidden", "growth");
    42	
    43	    await expect(
    44	      invitationService.inviteMember(tenant.actors.member, {
    45	        orgId: tenant.org.id,
    46	        email: "newperson@invite-forbidden.test",
    47	        role: "member",
    48	      }),
    49	    ).rejects.toBeInstanceOf(PermissionDeniedError);
    50	  });
    51	
    52	  // wouldExceedLimit(plan, "seats", seatsUsed) blocks the fourth seat on free.
    53	  it("refuses an invite that would exceed the plan's seat quota", async () => {
    54	    // The free plan tops out at 3 seats; createTenant already seeds 4 active
    55	    // members (owner, admin, member, viewer), so the org starts over quota.
    56	    const tenant = await createTenant("invite-seat-quota", "free");
    57	
    58	    await expect(
    59	      invitationService.inviteMember(tenant.actors.admin, {
    60	        orgId: tenant.org.id,
    61	        email: "onemore@invite-seat-quota.test",
    62	        role: "member",
    63	      }),
    64	    ).rejects.toThrow(/seats/);
    65	  });
    66	
    67	  // A bulk invite checks the seat quota once, for the whole batch.
    68	  it("checks the seat quota once for a bulk invite", async () => {
    69	    const tenant = await createTenant("invite-bulk-quota", "starter");
    70	
    71	    // Bring the org to 9 of its 10 starter seats: 4 from createTenant, 5 more
    72	    // inserted directly so only a single seat remains.
    73	    for (let i = 0; i < 5; i += 1) {
    74	      const user = await userRepo.insertUser({
    75	        email: `filler${i}@invite-bulk-quota.test`,
    76	        name: `Filler ${i}`,
    77	        passwordHash: "seed",
    78	      });
    79	      await memberRepo.insertMember(tenant.org.id, user.id, "member", null);
    80	    }
    81	    await expect(memberRepo.countActiveMembers(tenant.org.id)).resolves.toBe(9);
    82	
    83	    // A batch of two exceeds the one remaining seat; the check runs once for
    84	    // the whole batch, so nothing is created — not even the first invite.
    85	    await expect(
    86	      invitationService.inviteMembers(tenant.actors.admin, {
    87	        orgId: tenant.org.id,
    88	        invites: [
    89	          { email: "batch-a@invite-bulk-quota.test", role: "member" },
    90	          { email: "batch-b@invite-bulk-quota.test", role: "member" },
    91	        ],
    92	      }),
    93	    ).rejects.toThrow(/seats/);
    94	
    95	    await expect(
    96	      invitationRepo.countPendingInvitations(tenant.org.id),
    97	    ).resolves.toBe(0);
    98	
    99	    // The same-sized single invite fits inside the one remaining seat.
   100	    await expect(
   101	      invitationService.inviteMembers(tenant.actors.admin, {
   102	        orgId: tenant.org.id,
   103	        invites: [{ email: "batch-c@invite-bulk-quota.test", role: "member" }],
   104	      }),
   105	    ).resolves.toHaveLength(1);
   106	  });
   107	
   108	  // consumeRateLimit(orgId, "member:invite") throttles invite bursts.
   109	  it("rate-limits invites per organization", async () => {
   110	    const tenant = await createTenant("invite-rate-limit", "growth");
   111	    rateLimitState.allowed = false;
   112	
   113	    await expect(
   114	      invitationService.inviteMember(tenant.actors.admin, {
   115	        orgId: tenant.org.id,
   116	        email: "throttled@invite-rate-limit.test",
   117	        role: "member",
   118	      }),
   119	    ).rejects.toThrow(/rate limit/);
   120	  });
   121	
   122	  // member.invited carries the email and the granted role.
   123	  it("emits member.invited with the email and role", async () => {
   124	    const tenant = await createTenant("invite-emit", "growth");
   125	
   126	    let off: Unsubscribe | undefined;
   127	    const received = await new Promise((resolve) => {
   128	      off = subscribe("member.invited", (payload) => resolve(payload));
   129	      void invitationService.inviteMember(tenant.actors.admin, {
   130	        orgId: tenant.org.id,
   131	        email: "invitee@invite-emit.test",
   132	        role: "admin",
   133	      });
   134	    });
   135	    off?.();
   136	
   137	    expect(received).toMatchObject({
   138	      orgId: tenant.org.id,
   139	      email: "invitee@invite-emit.test",
   140	      role: "admin",
   141	    });
   142	  });
