/**
 * Membership rows. Every read is filtered by `orgId`; removal is a soft delete.
 *
 * Must call (do not reimplement): archivePatch, restorePatch, shouldFilterArchived
 */
import { and, count, desc, eq, inArray, isNull, like, or } from "drizzle-orm";
import { newId } from "@/lib/id";
import { archivePatch, restorePatch, shouldFilterArchived } from "@/lib/soft-delete";
import { getDb, members, users } from "@/server/db";
import { toIsoTimestamp } from "@/types/common";
import { orgPredicate } from "./base-repository";
import { compact, keysetPredicate, probeLimit, toPage } from "./_paging";
import { brandId, toMember, toUser } from "./_mappers";
import type { ListMembersInput } from "@/schemas/member";
import type {
  ArchiveScope,
  IsoTimestamp,
  MemberId,
  OrgId,
  Page,
  UserId,
} from "@/types/common";
import type { Member, MemberWithUser, Role } from "@/types/member";

/**
 * A removed member is archived, never deleted. Reads are live-only unless the
 * caller passes `includeArchived`, which only the re-admission path and the
 * conflict checks on a stale tab need.
 */
function liveMemberPredicate(scope: ArchiveScope = {}) {
  return shouldFilterArchived(scope) ? isNull(members.archivedAt) : undefined;
}

/**
 * The (org, user) lookup behind every actor resolution. A removed membership
 * is not returned, so `null` means "not a current member of this org".
 */
export async function findMember(
  orgId: OrgId,
  userId: UserId,
  scope: ArchiveScope = {},
): Promise<Member | null> {
  const row = getDb()
    .select()
    .from(members)
    .where(
      and(
        orgPredicate(members.orgId, orgId),
        eq(members.userId, userId),
        liveMemberPredicate(scope),
      ),
    )
    .get();
  return row ? toMember(row) : null;
}

export async function findMemberById(
  orgId: OrgId,
  memberId: MemberId,
  scope: ArchiveScope = {},
): Promise<Member | null> {
  const row = getDb()
    .select()
    .from(members)
    .where(
      and(
        orgPredicate(members.orgId, orgId),
        eq(members.id, memberId),
        liveMemberPredicate(scope),
      ),
    )
    .get();
  return row ? toMember(row) : null;
}

/**
 * The subset of `userIds` that are current members of the org: live and
 * active. One query, so the fan-out and the digest do not pay per recipient.
 */
export async function listCurrentMemberIds(
  orgId: OrgId,
  userIds: readonly UserId[],
): Promise<ReadonlySet<UserId>> {
  if (userIds.length === 0) return new Set();

  const rows = getDb()
    .select({ userId: members.userId })
    .from(members)
    .where(
      and(
        orgPredicate(members.orgId, orgId),
        inArray(members.userId, [...userIds]),
        eq(members.status, "active"),
        liveMemberPredicate(),
      ),
    )
    .all();

  return new Set(rows.map((row) => brandId<UserId>(row.userId)));
}

