import { afterAll, afterEach, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);
vi.mock("@/lib/rate-limit", async () => (await import("../server/_support/doubles/misc")).rateLimitModule);

import { subscribe } from "@/lib/event-bus";
import { hashToken } from "@/lib/hash";
import { AlreadyArchivedError } from "@/lib/soft-delete";
import * as invitationRepo from "@/server/repositories/invitation-repository";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as memberRepo from "@/server/repositories/member-repository";
import * as notificationPreferenceRepo from "@/server/repositories/notification-preference-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import * as usageRepo from "@/server/repositories/usage-repository";
import * as digestService from "@/server/services/digest-service";
import * as invitationService from "@/server/services/invitation-service";
import * as issueService from "@/server/services/issue-service";
import * as memberService from "@/server/services/member-service";
import * as notificationService from "@/server/services/notification-service";
import * as projectService from "@/server/services/project-service";
import * as sessionService from "@/server/services/session-service";
import { registerUsageListeners } from "@/server/services/usage-service";
import { rateLimitState } from "../server/_support/doubles/misc";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { IsoTimestamp, OrgId, UserId } from "@/types/common";

let cleanup: () => void;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  registerUsageListeners();
});

afterAll(() => {
  cleanup();
});

afterEach(() => {
  rateLimitState.allowed = true;
  rateLimitState.remaining = 100;
});

const FAR_FUTURE = "2099-01-01T00:00:00.000Z" as IsoTimestamp;

function principalFor(userId: UserId, orgId: OrgId) {
  return { userId, email: "x@example.test", activeOrgId: orgId, expiresAt: FAR_FUTURE };
}

async function memberIdOf(orgId: OrgId, userId: UserId) {
  const member = await memberRepo.findMember(orgId, userId, { includeArchived: true });
  if (!member) throw new Error("fixture member missing");
  return member.id;
}

describe("former members", () => {
  it("cannot resolve as an actor, switch in, or be found as a live member", async () => {
    const t = await createTenant("scratch-access", "growth");
    const memberId = await memberIdOf(t.org.id, t.userIds.viewer);
    await memberService.removeMember(t.actors.owner, { orgId: t.org.id, memberId });

    await expect(memberService.resolveActor(t.userIds.viewer, t.org.id)).resolves.toBeNull();
    await expect(
      sessionService.resolveActorForOrg(principalFor(t.userIds.viewer, t.org.id), t.org.slug),
    ).resolves.toBeNull();
    await expect(
      sessionService.switchActiveOrg(principalFor(t.userIds.viewer, t.org.id), { orgId: t.org.id }),
    ).rejects.toThrow(/not a member/);
    await expect(memberRepo.findMember(t.org.id, t.userIds.viewer)).resolves.toBeNull();
    await expect(orgRepo.listOrgsForUser(t.userIds.viewer)).resolves.toHaveLength(0);
  });

  it("refuses a second removal or a role change as a conflict and frees no seat", async () => {
    const t = await createTenant("scratch-conflict", "growth");
    await usageRepo.recomputeUsage(t.org.id);
    const memberId = await memberIdOf(t.org.id, t.userIds.viewer);

    await memberService.removeMember(t.actors.owner, { orgId: t.org.id, memberId });
    const seatsAfterRemoval = (await usageRepo.getUsage(t.org.id)).seatsUsed;
    expect(seatsAfterRemoval).toBe(3);

    const second = memberService.removeMember(t.actors.owner, { orgId: t.org.id, memberId });
    await expect(second).rejects.toBeInstanceOf(AlreadyArchivedError);
    await expect(
      memberService.updateMemberRole(t.actors.owner, { orgId: t.org.id, memberId, role: "admin" }),
    ).rejects.toBeInstanceOf(AlreadyArchivedError);

    expect((await usageRepo.getUsage(t.org.id)).seatsUsed).toBe(seatsAfterRemoval);
    const stored = await memberRepo.findMember(t.org.id, t.userIds.viewer, { includeArchived: true });
    expect(stored?.role).toBe("viewer");
  });

  it("is not notified of anything and is not a digest recipient", async () => {
    const t = await createTenant("scratch-notify", "growth");
    const memberId = await memberIdOf(t.org.id, t.userIds.viewer);
    await notificationPreferenceRepo.upsertPreference({
      orgId: t.org.id,
      userId: t.userIds.viewer,
      kind: "comment_created",
      inApp: true,
      email: true,
      digestOnly: true,
    } as never);
    await memberService.removeMember(t.actors.owner, { orgId: t.org.id, memberId });

    const rows = await notificationService.notify(
      t.org.id,
      "comment_created",
      [t.userIds.viewer, t.userIds.admin],
      { title: "New comment", body: "b", href: "/issues/1", actorId: t.userIds.owner },
    );
    expect(rows.map((row) => row.recipientId)).toEqual([t.userIds.admin]);

    const digest = await digestService.listDigestRecipients(t.org.id);
    expect(digest).not.toContain(t.userIds.viewer);
  });

  it("cannot be assigned work or made a project lead, and nothing is written", async () => {
    const t = await createTenant("scratch-assign", "growth");
    const memberId = await memberIdOf(t.org.id, t.userIds.viewer);
    await memberService.removeMember(t.actors.owner, { orgId: t.org.id, memberId });

