    expect(await issueRepo.countIssues(t.org.id, t.project.id)).toBe(issuesBefore);

    const projectsBefore = await projectRepo.countProjects(t.org.id);
    await expect(
      projectService.createProject(t.actors.admin, {
        orgId: t.org.id,
        name: "Ghost lead",
        key: "GHO",
        description: null,
        visibility: "org",
        leadId: t.userIds.viewer,
        color: "#000000",
        targetDate: null,
      } as never),
    ).rejects.toThrow(/not a current member/);
    expect(await projectRepo.countProjects(t.org.id)).toBe(projectsBefore);

    await expect(
      projectService.updateProject(t.actors.owner, {
        orgId: t.org.id,
        projectId: t.project.id,
        leadId: t.userIds.viewer,
      } as never),
    ).rejects.toThrow(/not a current member/);
    expect((await projectRepo.findProjectById(t.org.id, t.project.id))?.leadId).toBe(t.userIds.owner);
  });

  it("removal unassigns their issues and clears the projects they led", async () => {
    const t = await createTenant("scratch-release", "growth");
    const issue = await issueService.createIssue(
      t.actors.admin,
      issueInput(t.org.id, t.project.id, { assigneeId: t.userIds.member }),
    );
    await projectService.updateProject(t.actors.owner, {
      orgId: t.org.id,
      projectId: t.project.id,
      leadId: t.userIds.member,
    } as never);

    const memberId = await memberIdOf(t.org.id, t.userIds.member);
    await memberService.removeMember(t.actors.owner, { orgId: t.org.id, memberId });

    expect((await issueRepo.findIssueById(t.org.id, issue.id))?.assigneeId).toBeNull();
    expect((await projectRepo.findProjectById(t.org.id, t.project.id))?.leadId).toBeNull();
  });

  it("is re-admitted on the same row, listed once, with the invitation's role and inviter", async () => {
    const t = await createTenant("scratch-readmit", "growth");
    const memberId = await memberIdOf(t.org.id, t.userIds.viewer);
    const before = await memberRepo.findMember(t.org.id, t.userIds.viewer, { includeArchived: true });
    await memberService.removeMember(t.actors.owner, { orgId: t.org.id, memberId });

    const rawToken = "d".repeat(32);
    await invitationRepo.insertInvitation(
      t.org.id,
      { orgId: t.org.id, email: "viewer@scratch-readmit.test", role: "admin", expiresInDays: 14 },
      t.userIds.admin,
      hashToken(rawToken),
    );

    let joined: unknown;
    const off = subscribe("member.joined", (payload) => {
      joined = payload;
    });
    const member = await invitationService.acceptInvitation(t.userIds.viewer, { token: rawToken });
    off();

    expect(member.id).toBe(memberId);
    expect(member.archivedAt).toBeNull();
    expect(member.status).toBe("active");
    expect(member.role).toBe("admin");
    expect(member.invitedBy).toBe(t.userIds.admin);
    expect(member.joinedAt).not.toBeNull();
    expect(member.createdAt).toBe(before?.createdAt);
    expect(joined).toMatchObject({ memberId, userId: t.userIds.viewer, role: "admin" });

    const listed = await memberRepo.listMembers({ orgId: t.org.id, limit: 50, cursor: null });
    expect(listed.items.filter((row) => row.userId === t.userIds.viewer)).toHaveLength(1);
    await expect(orgRepo.listOrgsForUser(t.userIds.viewer)).resolves.toEqual(
      expect.arrayContaining([expect.objectContaining({ id: t.org.id })]),
    );
    await expect(memberRepo.countActiveMembers(t.org.id)).resolves.toBe(4);

    const rows = await notificationService.notify(
      t.org.id,
      "comment_created",
      [t.userIds.viewer],
      { title: "New comment", body: "b", href: "/issues/1", actorId: t.userIds.owner },
    );
    expect(rows.map((row) => row.recipientId)).toEqual([t.userIds.viewer]);
  });

  it("a current member accepting an invitation changes nothing but uses it up", async () => {
    const t = await createTenant("scratch-current", "growth");
    const before = await memberRepo.findMember(t.org.id, t.userIds.admin);
    const rawToken = "e".repeat(32);
    await invitationRepo.insertInvitation(
      t.org.id,
      { orgId: t.org.id, email: "admin@scratch-current.test", role: "viewer", expiresInDays: 14 },
      t.userIds.owner,
      hashToken(rawToken),
    );

    const member = await invitationService.acceptInvitation(t.userIds.admin, { token: rawToken });
    expect(member).toMatchObject({ id: before?.id, role: "admin", status: "active" });
    expect(member.archivedAt).toBeNull();
    await expect(memberRepo.countActiveMembers(t.org.id)).resolves.toBe(4);

    await expect(
      invitationService.acceptInvitation(t.userIds.admin, { token: rawToken }),
    ).rejects.toThrow(/already been accepted/);
  });
});

